-- Safe anti-join (handles NULLs properly unlike NOT IN)
SELECT u.id FROM users u
WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);

WITH RECURSIVE org_tree AS (
  SELECT id, manager_id, name, 1 AS lvl FROM emp WHERE manager_id IS NULL
  UNION ALL
  SELECT e.id, e.manager_id, e.name, t.lvl + 1 FROM emp e JOIN org_tree t ON e.manager_id = t.id
)
SELECT * FROM org_tree;

-- SARGable range filter + covering index
CREATE INDEX idx_orders_date_cov ON orders (created_at) INCLUDE (total, status);
SELECT total, status FROM orders WHERE created_at >= '2026-01-01' AND created_at < '2027-01-01';

BEGIN;
UPDATE inventory SET qty = qty - 1 WHERE sku = 'A1' AND qty >= 1;
COMMIT;

WITH ranked AS (
  SELECT name, department_id, salary,
         DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS rnk
  FROM employees
)
SELECT name, department_id, salary FROM ranked WHERE rnk <= 2;

WITH dups AS (
  SELECT id, ROW_NUMBER() OVER (PARTITION BY email ORDER BY created_at ASC, id ASC) AS rn
  FROM users
)
DELETE FROM users WHERE id IN (SELECT id FROM dups WHERE rn > 1);

SELECT * FROM users WHERE deleted_at IS NULL;
-- NULL-safe equality:
SELECT * FROM t WHERE a IS DISTINCT FROM b;

SELECT u.id, u.name, o.id AS order_id, o.total
FROM users u LEFT JOIN orders o ON o.user_id = u.id
WHERE u.id IN (1, 2, 3, 4);
